"""Compose only reviewed transaction surfaces from real full-generator outputs."""
import copy
import hashlib
import json
import os
from pathlib import Path
import sys

ROOT=Path(__file__).resolve().parent.parent
TARGETS={"/api/account/transactions/","/api/account/transactions/{id}/"}
CLOSURE={"PaginatedTransactionList","TransactionCreateRequest","TransactionCreated","Transaction","TradeActionEnum"}
OUTPUTS=["schema.yml","docs/testing/api/openapi.yaml","docs/testing/api/openapi.json"]


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def differences(old,new,path=""):
    if type(old) is not type(new):
        return [path]
    if isinstance(old,dict):
        out=[]
        for key in sorted(set(old)|set(new)):
            at=path+"/"+str(key)
            out.extend([at] if key not in old or key not in new else differences(old[key],new[key],at))
        return out
    return [] if old==new else [path]


def references(value):
    result=set()
    if isinstance(value,dict):
        for key,item in value.items():
            if key=="$ref":
                assert isinstance(item,str) and item.startswith("#/components/schemas/")
                result.add(item.rsplit("/",1)[-1])
            else:
                result.update(references(item))
    elif isinstance(value,list):
        for item in value:
            result.update(references(item))
    return result


def main() -> None:
    assert len(sys.argv)==2
    prefix=sys.argv[1]
    assert prefix in {"fee-a-bbc7-root-4"}
    ref=json.loads((ROOT/".tmp"/f"{prefix}-reference.json").read_text(encoding="utf-8"))
    export=Path(ref["export"])
    out=ROOT/".tmp"/f"{prefix}-openapi-composition.json"
    assert not out.exists()
    base=json.loads((ROOT/OUTPUTS[2]).read_text(encoding="utf-8"))
    generated=json.loads((export/OUTPUTS[2]).read_text(encoding="utf-8"))
    assert base["info"]==generated["info"] and base["openapi"]==generated["openapi"]
    assert base["components"]["securitySchemes"]==generated["components"]["securitySchemes"]
    schemas=generated["components"]["schemas"]
    required=references({name:generated["paths"][name] for name in TARGETS})
    pending=list(required)
    while pending:
        for name in references(schemas[pending.pop()]):
            if name not in required:
                required.add(name)
                pending.append(name)
    assert required==CLOSURE
    allowed_transaction={"/properties/commission/nullable","/properties/slippage","/properties/stamp_duty/nullable",
        "/properties/transfer_fee/nullable",*[f"/properties/{name}_known" for name in ("commission","slippage","stamp_duty","transfer_fee")]}
    allowed_request={"/properties/commission/nullable","/properties/slippage","/properties/stamp_duty","/properties/transfer_fee",
        "/properties/notes/default","/properties/portfolio/minimum","/properties/position/minimum"}
    old_schemas=base["components"]["schemas"]
    assert set(differences(old_schemas["Transaction"],schemas["Transaction"]))==allowed_transaction
    assert set(differences(old_schemas["TransactionCreateRequest"],schemas["TransactionCreateRequest"]))==allowed_request
    assert schemas["TransactionCreateRequest"]["properties"]["notes"]["default"]==""
    for name in ("portfolio","position"):
        assert schemas["TransactionCreateRequest"]["properties"][name]["minimum"]==1
    for name in ("TradeActionEnum","PaginatedTransactionList"):
        assert old_schemas[name]==schemas[name]
    assert "TransactionCreated" not in old_schemas
    created=schemas["TransactionCreated"]
    assert "id" not in created["properties"] and "notional" not in created["properties"]
    assert created["required"]==old_schemas["TransactionCreate"]["required"]
    for name in ("commission","slippage","stamp_duty","transfer_fee"):
        assert created["properties"][name]["nullable"] is True
        assert created["properties"][name+"_known"]=={"type":"boolean","readOnly":True,"nullable":True}
    for name in TARGETS:
        paths=set(differences(base["paths"][name],generated["paths"][name]))
        expected={"/get/description"}
        if name.endswith("transactions/"):
            expected|={"/post/description","/post/responses/201/content/application/json/schema/$ref"}
        assert paths==expected,(name,paths)
    composed=copy.deepcopy(base)
    for name in TARGETS:
        composed["paths"][name]=copy.deepcopy(generated["paths"][name])
    for name in CLOSURE:
        composed["components"]["schemas"][name]=copy.deepcopy(schemas[name])
    if list(old_schemas)==sorted(old_schemas):
        composed["components"]["schemas"]=dict(sorted(composed["components"]["schemas"].items()))
    assert composed["components"]["schemas"]["TransactionCreate"]==old_schemas["TransactionCreate"]
    assert {k:v for k,v in composed["paths"].items() if k not in TARGETS}=={k:v for k,v in base["paths"].items() if k not in TARGETS}
    assert {k:v for k,v in composed["components"]["schemas"].items() if k not in CLOSURE}=={k:v for k,v in old_schemas.items() if k not in CLOSURE}
    sys.path[:0]=[str(export),str(export/".tmp")]
    os.environ["DJANGO_SETTINGS_MODULE"]="ash_formal_calendar_sqlite_settings"
    import ash_domain_local_network_fence as fence
    import django
    django.setup()
    import yaml
    from drf_spectacular.renderers import OpenApiJsonRenderer,OpenApiYamlRenderer
    full_pins={}
    base_pins={}
    for name in OUTPUTS:
        source=(export/name).read_bytes()
        original=(ROOT/name).read_bytes()
        assert sha(original.replace(b"\r\n",b"\n"))==ref["output_base_lf_sha256"][name]
        parse=json.loads if name.endswith(".json") else yaml.safe_load
        assert parse(source)==generated and parse(original)==base
        target=export/".tmp/scoped-openapi-full-originals"/name
        assert not target.exists()
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(source)
        full_pins[name]=sha(source)
        base_pins[name]=sha(original)
    rendered_json=OpenApiJsonRenderer().render(composed)
    rendered_yaml=OpenApiYamlRenderer().render(composed)
    assert json.loads(rendered_json)==composed and yaml.safe_load(rendered_yaml)==composed
    assert not fence._attempts
    for name in OUTPUTS:
        (export/name).write_bytes(rendered_json if name.endswith(".json") else rendered_yaml)
    report={"status":"bounded_official_output_composition_reviewed", "source_tree":ref["source_tree"],"source_commit":ref["source_commit"],
        "target_paths":sorted(TARGETS),"schema_reference_closure":sorted(CLOSURE),
        "all_unrelated_paths_components_security_and_legacy_component_preserved":True,
        "root_approved_request_metadata":["notes.default empty matches existing normalized empty notes", "portfolio/position minimum=1 matches typed ID validation"],
        "full_generator_output_raw_sha256":full_pins,"base_artifact_raw_sha256":base_pins,
        "output_lf_sha256":{name:sha((export/name).read_bytes().replace(b"\r\n",b"\n")) for name in OUTPUTS},
        "old_global_projection_drift_excluded":True,"not_a_full_schema_freshness_claim":True,
        "official_renderers":["OpenApiJsonRenderer","OpenApiYamlRenderer"],"driver_raw_sha256":sha(Path(__file__).read_bytes())}
    out.write_text(json.dumps(report,indent=2)+"\n",encoding="utf-8")
    print(json.dumps({"record":str(out),"status":report["status"],"paths":len(TARGETS),"closure":len(CLOSURE)}),flush=True)


if __name__ == "__main__":
    main()

